1	"use client";
2	
3	// src/components/Projekte/ParkLiveDemo.js – Demo-Live-Ansicht des Gläsernen Solarparks (Welle 4)
4	//
5	// Zeigt die DEMO-Erzeugung des Beispielparks: aktuelle Leistung, Tagessumme und Tagesverlauf
6	// aus dem deterministischen Demo-Modell (src/lib/projekte/glaesernerPark.js). KEINE echten
7	// Messdaten – deshalb überall das Entwurfs-Badge „Beispieldaten – echte Parkdaten folgen“
8	// und die Beschriftung „Demo“ statt „Live“. Erst nach Mount wird die Uhrzeit gelesen
9	// (kein Hydration-Versatz), danach Aktualisierung jede Minute.
10	
11	import { useEffect, useState } from "react";
12	import { Clock, Sun, Zap } from "lucide-react";
13	import Sparkline from "@/components/ui/Sparkline";
14	import Badge from "@/components/ui/Badge";
15	import { cn } from "@/components/ui/cn";
16	import { useTexte } from "@/components/Sprache/SpracheKontext";
17	import { fmtZahl } from "@/lib/sprache/format";
18	import { demoLeistungKw, demoTagesMwh, demoTagesverlauf } from "@/lib/projekte/glaesernerPark";
19	
20	const TEXTE = {
21	  de: {
22	    sprache: "de",
23	    badge: "Beispieldaten – echte Parkdaten folgen",
24	    titel: "Erzeugung heute · Demo-Modell",
25	    jetzt: "Leistung jetzt",
26	    heute: "heute bisher",
27	    anteil: (p) => `${p} % der Parkleistung`,
28	    verlauf: "Tagesverlauf im Demo-Modell",
29	    verlaufLabel: "Demo-Tagesverlauf der Erzeugung von 0 bis 24 Uhr",
30	    stand: (u) => `Demo-Modell · Stand ${u} Uhr`,
31	    laedt: "Demo-Ansicht wird geladen …",
32	    nacht: "Nacht – der Park erzeugt gerade keinen Strom.",
33	  },
34	  en: {
35	    sprache: "en",
36	    badge: "Example data – real park data to follow",
37	    titel: "Generation today · demo model",
38	    jetzt: "Output now",
39	    heute: "so far today",
40	    anteil: (p) => `${p} % of park capacity`,
41	    verlauf: "Daily curve, demo model",
42	    verlaufLabel: "Demo daily generation curve from midnight to midnight",
43	    stand: (u) => `Demo model · as of ${u}`,
44	    laedt: "Loading the demo view …",
45	    nacht: "Night – the park is not generating right now.",
46	  },
47	};
48	
49	export default function ParkLiveDemo({ park, dunkel = true, className }) {
50	  const w = useTexte(TEXTE);
51	  const [jetzt, setJetzt] = useState(null);
52	
53	  useEffect(() => {
54	    setJetzt(new Date());
55	    const t = setInterval(() => setJetzt(new Date()), 60_000);
56	    return () => clearInterval(t);
57	  }, []);
58	
59	  const rahmen = cn(
60	    "rounded-[2rem] p-6 ring-1 sm:p-7",
61	    dunkel ? "ov-glass text-white ring-white/15" : "bg-white text-ink-900 ring-ink-200/70 shadow-e2",
62	    className
63	  );
64	
65	  if (!jetzt) {
66	    return (
67	      <div className={rahmen} role="status" aria-live="polite">
68	        <Badge ton={dunkel ? "dunkel" : "warn"}>{w.badge}</Badge>
69	        <p className={cn("mt-6 text-[15px]", dunkel ? "text-white/70" : "text-ink-600")}>{w.laedt}</p>
70	        <div aria-hidden="true" className="mt-6 h-24 animate-pulse rounded-2xl bg-current opacity-[0.07]" />
71	      </div>
72	    );
73	  }
74	
75	  const kw = demoLeistungKw(park, jetzt);
76	  const mwhHeute = demoTagesMwh(park, jetzt);
77	  const anteil = Math.round((kw / park.kennzahlen.kwp) * 100);
78	  const verlauf = demoTagesverlauf(park, jetzt).map((p) => p.kw);
79	  const en = w.sprache === "en";
80	  const uhr = jetzt.toLocaleTimeString(en ? "en-GB" : "de-DE", { hour: "2-digit", minute: "2-digit" });
81	  const z = (n, s = 0) => fmtZahl(n, s, w.sprache);
82	  const dim = dunkel ? "text-white/60" : "text-ink-500";
83	
84	  return (
85	    <div className={rahmen}>
86	      <div className="flex flex-wrap items-center justify-between gap-3">
87	        <p className="font-display text-[17px] font-bold">{w.titel}</p>
88	        <Badge ton={dunkel ? "dunkel" : "warn"}>{w.badge}</Badge>
89	      </div>
90	
91	      <dl className="mt-6 grid gap-5 sm:grid-cols-2">
92	        <div>
93	          <dt className={cn("flex items-center gap-1.5 text-[13px] font-semibold uppercase tracking-[0.08em]", dim)}>
94	            <Zap aria-hidden="true" className="h-3.5 w-3.5" /> {w.jetzt}
95	          </dt>
96	          <dd className="mt-1.5">
97	            <span className="font-display text-[34px] font-bold leading-none tabular-nums">{z(kw)}</span>
98	            <span className={cn("ml-1.5 text-[15px] font-semibold", dim)}>kW</span>
99	            <p className={cn("mt-1 text-[13px]", dim)}>{kw > 0 ? w.anteil(z(anteil)) : w.nacht}</p>
100	          </dd>
101	        </div>
102	        <div>
103	          <dt className={cn("flex items-center gap-1.5 text-[13px] font-semibold uppercase tracking-[0.08em]", dim)}>
104	            <Sun aria-hidden="true" className="h-3.5 w-3.5" /> {w.heute}
105	          </dt>
106	          <dd className="mt-1.5">
107	            <span className="font-display text-[34px] font-bold leading-none tabular-nums">{z(mwhHeute, 1)}</span>
108	            <span className={cn("ml-1.5 text-[15px] font-semibold", dim)}>MWh</span>
109	          </dd>
110	        </div>
111	      </dl>
112	
113	      <div className="mt-6">
114	        <p className={cn("mb-2 text-[13px] font-semibold", dim)}>{w.verlauf}</p>
115	        <Sparkline werte={verlauf} breite={320} hoehe={64} ton={dunkel ? "hell" : "marke"} label={w.verlaufLabel} className="w-full" />
116	      </div>
117	
118	      <p className={cn("mt-4 flex items-center gap-1.5 text-[12.5px]", dim)}>
119	        <Clock aria-hidden="true" className="h-3.5 w-3.5" /> {w.stand(uhr)}
120	      </p>
121	    </div>
122	  );
123	}
